#!/usr/bin/env python3
"""DOCH: 'Lernen auf Deutsch' Teil 6 - wortb, fehler, lang, praet, plural, komp, indef. Eigene Formulierung. Idempotent."""
import sys,re
p="index.html"; s=open(p,encoding="utf-8").read()
if "Lies ein langes Wort von hinten" in s: sys.exit("already patched")
miss=[]
def apply(k,R):
    global s
    a=s.find("GT.%s={"%k); b=s.find("\nGT.",a+10)
    if b<0: b=s.find("\n/* =====",a+10)
    assert a>0 and b>a,k
    seg=s[a:b]
    for o,n in R:
        if seg.count(o)<1: miss.append((k,o[:70])); continue
        seg=seg.replace(o,n)
    s=s[:a]+seg+s[b:]
